// GitHub commit & PR velocity (#402) — daily commit/PR trend with a 7d/14d range toggle. Extracted
// from GitHubPulse's inline card into its own composable record; adds the loading + empty states the
// inline version didn't have.
import { useState } from "react";
import { CardHead, LineArea, Legend, RangeToggle, useTip } from "@/shared/ui/charts";
import { SkeletonChart } from "@/shared/ui/feedback/Skeleton";
import { CardEmpty } from "@/shared/ui/feedback/CardStates";
import { Card } from "@/shared/ui/data/Card";

interface VelocitySlice { labels: string[]; commits: number[]; merged: number[]; opened: number[]; adds: number[]; dels: number[] }

function sliceVelocity(v: VelocitySlice, range: string): VelocitySlice {
  const n = range === "7d" ? 7 : v.labels.length;
  const last = <T,>(a: T[]) => a.slice(-n);
  return { labels: last(v.labels), commits: last(v.commits), merged: last(v.merged), opened: last(v.opened), adds: last(v.adds), dels: last(v.dels) };
}

const DEMO_VELOCITY: VelocitySlice = {
  labels: Array.from({ length: 14 }, (_, i) => `d${i + 1}`),
  commits: [3, 5, 2, 6, 4, 7, 5, 3, 6, 4, 8, 5, 6, 4],
  merged: [1, 2, 1, 3, 2, 3, 2, 1, 3, 2, 4, 2, 3, 2],
  opened: [2, 3, 2, 4, 3, 4, 3, 2, 4, 3, 5, 3, 4, 3],
  adds: [120, 200, 90, 260, 180, 300, 210, 130, 240, 170, 320, 200, 250, 180],
  dels: [40, 60, 30, 80, 50, 90, 60, 40, 70, 50, 100, 60, 80, 50],
};

export function Velocity({ velocity = DEMO_VELOCITY, loading = false }: { velocity?: VelocitySlice; loading?: boolean }) {
  const [range, setRange] = useState("14d");
  const tip = useTip();
  const d = sliceVelocity(velocity, range);
  const total = d.commits.reduce((a, b) => a + b, 0) + d.opened.reduce((a, b) => a + b, 0) + d.merged.reduce((a, b) => a + b, 0);
  return (
    <Card>
      <CardHead title="Commit & PR velocity" hint="daily commits, PRs opened vs merged"
        right={<RangeToggle value={range} onChange={setRange} options={["7d", "14d"]} />} />
      {loading ? <SkeletonChart height={160} /> : total === 0 ? (
        <CardEmpty icon="○" title="No activity yet" hint="Commits and PRs will appear here once this repo has some." />
      ) : (
        <>
          <LineArea labels={d.labels} height={160} tip={tip} series={[
            { name: "commits", color: "var(--info)", data: d.commits },
            { name: "PRs opened", color: "var(--fg-muted)", data: d.opened, fill: false, dash: "4 3", dotR: 1.8 },
            { name: "PRs merged", color: "var(--accent)", data: d.merged, fill: false },
          ]} />
          <Legend style={{ marginTop: 8 }} items={[
            { color: "var(--info)", label: "commits" },
            { color: "var(--fg-muted)", label: "PRs opened" },
            { color: "var(--accent)", label: "PRs merged" },
          ]} />
        </>
      )}
      {tip.node}
    </Card>
  );
}
